/* What a file says about ONE stock: its row, or why there is none. "Not yet fetched" = the file has no row and no error for the stock;
   "Unavailable from source" = the updater recorded that Upstox does not list it; a recorded request failure is said as such. Nothing is inferred beyond that. */
var MLABEL={pe:"P/E",pb:"P/B",roe:"ROE",roce:"ROCE",roa:"ROA",ev_ebitda:"EV/EBITDA"};
function stockStatus(doc,s,row){
  if(!doc)return null;
  if(row){var bits=[];if(typeof row.fetched==="string"&&/^\d{4}-\d{2}-\d{2}$/.test(row.fetched))bits.push("last updated "+esc(row.fetched));
    if(Array.isArray(row.missing)&&row.missing.length)bits.push("not returned by the source: "+row.missing.map(function(m){return esc(MLABEL[m]||m)}).join(", "));
    return bits.length?"this stock: "+bits.join("; "):null}
  var e=Array.isArray(doc.errors)?doc.errors.filter(function(x){return x&&x.symbol===s})[0]:null;
  if(e&&/not found/i.test(String(e.error||"")))return"this stock: unavailable from source (not in the Upstox equity list)";
  if(e)return"this stock: not available (the last request failed)";
  return"this stock: not yet fetched"}

